async function refreshMarket(){const b=document.querySelector('[data-action=refreshPrice]');if(b)b.disabled=true;try{const res=await fetch('/.netlify/functions/market-feed',{cache:'no-store'});let body={};try{body=await res.json()}catch{}if(!res.ok)throw Error(body.message||'HTTP '+res.status);if(!Array.isArray(body.quotes))throw Error('API response ไม่ใช่รายการราคา');const known=new Set(prices().map(q=>[q.kind,q.source,q.grade,q.observed,q.price].join('|')));let count=0;for(const q of body.quotes){const kind=q.kind,price=Number(q.price),ts=Date.parse(q.observed),u=safeUrl(q.url);if(!['THAI','LME','FX'].includes(kind)||!q.source||!Number.isFinite(price)||price<=0||!Number.isFinite(ts)||ts>Date.now()+60000||!u)continue;if(kind==='THAI'&&(!q.grade||q.unit!=='THB_KG'||q.vat!=='EX_VAT'))continue;if(kind==='LME'&&(q.unit!=='USD_TON'||!['Cash','3-Month'].includes(q.lmeType)))continue;if(kind==='FX'&&q.unit!=='THB_USD')continue;const key=[q.kind,q.source,q.grade,q.observed,q.price].join('|');if(known.has(key))continue;known.add(key);await store('price',{...q,id:uid(),verified:q.verified===true,recorded:new Date().toISOString()});count++}
 render();toast(count?'ดึงข้อมูลราคาใหม่ '+count+' รายการ':'ไม่พบราคาใหม่ / ข้อมูลเดิมยังคงอยู่')
 }catch(e){toast('ดึงราคาออนไลน์ไม่ได้: '+e.message+' • ข้อมูลเดิมไม่ถูกลบ')}finally{if(b)b.disabled=false}}
// Import is intentionally replace-only, avoiding accidental duplicate lots on restore.
document.addEventListener('change',async e=>{
 if(e.target.id!=='importBackupFile')return;
 const file=e.target.files?.[0];if(!file)return;
 try{
  if(file.size>20*1024*1024)throw Error('ไฟล์ใหญ่เกิน 20 MB');
  const b=JSON.parse(await file.text());
  if(!Array.isArray(b.records)||![2,3].includes(Number(b.version)))throw Error('รูปแบบ Backup ไม่ถูกต้อง');
  if(b.records.length>100000)throw Error('จำนวนรายการมากเกินขอบเขต');
  const valid=new Set(['lot','cable','quote','price']);
  if(!b.records.every(r=>r&&typeof r.id==='string'&&r.id.length<200&&valid.has(r.record_type)&&r.payload&&typeof r.payload==='object'&&!Array.isArray(r.payload)))throw Error('ข้อมูลในไฟล์ไม่ถูกต้อง');
  if(!confirm('การกู้คืนจะเขียนทับข้อมูลทั้งหมดในอุปกรณ์นี้ กรุณาสำรองไฟล์ปัจจุบันก่อน ยืนยันกู้คืน '+b.records.length+' รายการ?'))return;
  records=structuredClone(b.records);await persist();draft=null;quoteDraft=null;render();toast('กู้คืนข้อมูล '+records.length+' รายการสำเร็จ');
 }catch(err){toast('กู้คืนไม่สำเร็จ: '+err.message)}finally{e.target.value=''}
});
async function init(){
 try{
  const [c,q]=await Promise.all([fetch('/data/cables.json').then(r=>{if(!r.ok)throw Error('cables.json');return r.json()}),fetch('/data/monthly_quote_sample.json').then(r=>{if(!r.ok)throw Error('monthly_quote_sample.json');return r.json()})]);baseCables=c;sampleQuote=q;
 }catch(e){toast('โหลดฐานข้อมูลเริ่มต้นไม่สำเร็จ: '+e.message);baseCables=[];sampleQuote={id:'SEED',prices:{},month:'',supplier:''}}
 try{await loadCache()}catch(e){toast('เปิดฐานข้อมูลในเครื่องไม่สำเร็จ: '+e.message)}
 render();
}
